import{_ as t,c as e,o as r,aj as i}from"./chunks/framework.D4QnD388.js";const f=JSON.parse('{"title":"量化研究入门","description":"","frontmatter":{"layout":"home","title":"量化研究入门","hero":{"name":"量化研究入门","text":"基于多因子股票量化投研框架","tagline":"湖南大学金融科技协会 Quant Group 开源教程","image":{"src":"/pic/image.png","alt":"量化投研框架"},"actions":[{"theme":"brand","text":"开始阅读","link":"/guide/"},{"theme":"alt","text":"论文日报","link":"/arxiv/"},{"theme":"alt","text":"GitHub","link":"https://github.com/Barca0412/Introduction-to-Quantitative-Finance"}]},"features":[{"title":"数据源与另类数据","details":"JQData、Tushare、AKShare 等金融数据获取接口","link":"/data/"},{"title":"因子挖掘","details":"基本面因子、技术因子、机器学习因子、LLM因子挖掘","link":"/factors/"},{"title":"回测框架","details":"Backtrader、Qlib、QUANTAXIS 等量化回测工具","link":"/backtest/"},{"title":"投资组合优化","details":"均值方差优化、Barra多因子风控模型","link":"/portfolio/"},{"title":"AI+金融论文日报","details":"每日自动抓取arXiv论文，LLM生成中文概述与标签分类","link":"/arxiv/"},{"title":"公开资源","details":"量化论坛、在线课程、开源工具汇总","link":"/resources/"}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),n={name:"index.md"};function o(l,a,h,c,s,u){return r(),e("div",null,[...a[0]||(a[0]=[i('<div style="display:flex;justify-content:center;gap:10px;margin:20px 0;"><a href="https://github.com/Barca0412/Introduction-to-Quantitative-Finance"><img src="https://img.shields.io/github/stars/Barca0412/Introduction-to-Quantitative-Finance?style=social" alt="GitHub stars"></a><a href="https://github.com/Barca0412/Introduction-to-Quantitative-Finance/fork"><img src="https://img.shields.io/github/forks/Barca0412/Introduction-to-Quantitative-Finance?style=social" alt="GitHub forks"></a></div><div style="display:flex;justify-content:center;flex-wrap:wrap;gap:20px;margin:30px 0;"><div style="text-align:center;"></div><div style="text-align:center;"><img src="https://api.star-history.com/svg?repos=Barca0412/Introduction-to-Quantitative-Finance&amp;type=Date" alt="Star History Chart" style="max-width:400px;"></div></div><hr><h2 id="这是什么" tabindex="-1">这是什么 <a class="header-anchor" href="#这是什么" aria-label="Permalink to &quot;这是什么&quot;">​</a></h2><p><strong>量化研究入门</strong>是由湖南大学金融科技协会 Quant Group 维护的中文开源知识库，帮助学习者建立从金融数据、因子研究、回测到组合优化的量化投研工作流。项目同时提供每日更新的 <strong>AI + Finance arXiv Radar</strong>：从 10 个 arXiv 分类筛选论文，并提供标签、关键词和中文概述。</p><p>适合希望学习多因子量化、寻找开源回测工具，或跟踪 AI、LLM 与智能体在金融研究中最新进展的学生、研究者和开发者。</p><h2 id="量化研究学习路径" tabindex="-1">量化研究学习路径 <a class="header-anchor" href="#量化研究学习路径" aria-label="Permalink to &quot;量化研究学习路径&quot;">​</a></h2><ol><li>从<a href="/Introduction-to-Quantitative-Finance/guide/">多因子投研框架</a>理解研究流程和常见术语。</li><li>对比<a href="/Introduction-to-Quantitative-Finance/data/">金融数据与另类数据</a>，选择数据获取方式。</li><li>学习<a href="/Introduction-to-Quantitative-Finance/factors/">基本面、技术、机器学习与 LLM 因子</a>。</li><li>使用<a href="/Introduction-to-Quantitative-Finance/backtest/">回测框架</a>验证策略，再进入<a href="/Introduction-to-Quantitative-Finance/portfolio/">组合优化</a>与风险管理。</li></ol><h2 id="ai-finance-论文雷达如何工作" tabindex="-1">AI + Finance 论文雷达如何工作 <a class="header-anchor" href="#ai-finance-论文雷达如何工作" aria-label="Permalink to &quot;AI + Finance 论文雷达如何工作&quot;">​</a></h2><p>Radar 每日抓取近期 arXiv 论文，为相关研究生成主题标签、关键词、中文摘要和趋势统计。阅读<a href="/Introduction-to-Quantitative-Finance/arxiv/">论文雷达</a>可查看结果；关于筛选范围、分类和数据流程，请见<a href="/Introduction-to-Quantitative-Finance/arxiv/about.html">方法说明</a>。原始研究结论应以链接到的 arXiv 论文为准。</p><p>本项目用于教育与研究，不构成投资建议。</p><h2 id="quant-项目精选" tabindex="-1">Quant 项目精选 <a class="header-anchor" href="#quant-项目精选" aria-label="Permalink to &quot;Quant 项目精选&quot;">​</a></h2><h3 id="多因子量化框架" tabindex="-1">多因子量化框架 <a class="header-anchor" href="#多因子量化框架" aria-label="Permalink to &quot;多因子量化框架&quot;">​</a></h3><ul><li><a href="https://github.com/microsoft/qlib" target="_blank" rel="noreferrer">microsoft/qlib</a> - AI导向量化投资平台，支持自动因子挖掘</li><li><a href="https://github.com/etccapital/MultiFactor" target="_blank" rel="noreferrer">etccapital/MultiFactor</a> - 基于华泰研报的多因子回测框架</li></ul><h3 id="回测框架" tabindex="-1">回测框架 <a class="header-anchor" href="#回测框架" aria-label="Permalink to &quot;回测框架&quot;">​</a></h3><ul><li><a href="https://github.com/kernc/backtesting.py" target="_blank" rel="noreferrer">kernc/backtesting.py</a> - 简洁高效Python回测库</li><li><a href="https://github.com/polakowo/vectorbt" target="_blank" rel="noreferrer">polakowo/vectorbt</a> - 极速向量化回测</li></ul><h3 id="因子挖掘与机器学习" tabindex="-1">因子挖掘与机器学习 <a class="header-anchor" href="#因子挖掘与机器学习" aria-label="Permalink to &quot;因子挖掘与机器学习&quot;">​</a></h3><ul><li><a href="https://github.com/RndmVariableQ/AlphaAgent" target="_blank" rel="noreferrer">RndmVariableQ/AlphaAgent</a> - KDD 2025 LLM驱动因子挖掘</li><li><a href="https://github.com/microsoft/RD-Agent" target="_blank" rel="noreferrer">microsoft/RD-Agent</a> - 多Agent自动化R&amp;D</li></ul><h3 id="强化学习交易" tabindex="-1">强化学习交易 <a class="header-anchor" href="#强化学习交易" aria-label="Permalink to &quot;强化学习交易&quot;">​</a></h3><ul><li><a href="https://github.com/AI4Finance-Foundation/FinRL" target="_blank" rel="noreferrer">AI4Finance-Foundation/FinRL</a> - 开源金融强化学习框架</li></ul><h3 id="高频交易" tabindex="-1">高频交易 <a class="header-anchor" href="#高频交易" aria-label="Permalink to &quot;高频交易&quot;">​</a></h3><ul><li><a href="https://github.com/nkaz001/hftbacktest" target="_blank" rel="noreferrer">nkaz001/hftbacktest</a> - 高频交易和做市回测框架</li></ul><hr><h2 id="量化论坛" tabindex="-1">量化论坛 <a class="header-anchor" href="#量化论坛" aria-label="Permalink to &quot;量化论坛&quot;">​</a></h2><p><strong>国内</strong>: <a href="https://www.joinquant.com/" target="_blank" rel="noreferrer">聚宽</a> | <a href="https://www.vnpy.com/forum/" target="_blank" rel="noreferrer">VeighNa</a> | <a href="https://bbs.myquant.cn/" target="_blank" rel="noreferrer">掘金</a> | <a href="https://bigquant.com/" target="_blank" rel="noreferrer">BigQuant</a></p><p><strong>国外</strong>: <a href="https://www.quantstart.com/" target="_blank" rel="noreferrer">Quantstart</a> | <a href="https://allocatesmartly.com/" target="_blank" rel="noreferrer">Allocate Smartly</a> | <a href="https://research.macrosynergy.com/" target="_blank" rel="noreferrer">Macrosynergy</a></p><hr><h2 id="联系方式" tabindex="-1">联系方式 <a class="header-anchor" href="#联系方式" aria-label="Permalink to &quot;联系方式&quot;">​</a></h2><ul><li>Email: <a href="mailto:qgh124430@hnu.edu.cn" target="_blank" rel="noreferrer">qgh124430@hnu.edu.cn</a></li><li>Wechat: qgh985695077</li><li><a href="https://www.guohaoqi.cn/hft-association" target="_blank" rel="noreferrer">湖南大学金融科技协会介绍</a></li></ul>',29)])])}const p=t(n,[["render",o]]);export{f as __pageData,p as default};
